#include "mspa/psychology/beliefs.hpp"
#include "mspa/psychology/personality.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {
namespace{std::uint64_t next_id(const AgentPsychState&a){std::uint64_t n=1;for(const auto&b:a.beliefs)n=std::max(n,b.id.value()+1);return n;}}
Result<BeliefId> BeliefSystem::add(AgentPsychState&a,const Proposition&p,float c,float e,PsychTime t,BeliefSource s,AgentId src)const{if(!a.id.valid()||!p.predicate.valid()||!p.name_space.valid()||!std::isfinite(c)||!std::isfinite(e))return make_error(ErrorCode::InvalidArgument,"invalid belief");BeliefState b{};b.id=BeliefId(next_id(a));b.proposition=p;b.certainty=std::clamp(c,0.0f,1.0f);b.emotional_load=std::clamp(e,-1.0f,1.0f);b.source=s;b.source_agent=src;b.updated_at=t;a.beliefs.push_back(b);return b.id;}
Result<BeliefId> BeliefSystem::add(AgentPsychState&a,PredicateId p,float c,float e,PsychTime t)const{Proposition q{};q.predicate=p;q.name_space=NamespaceId(1);return add(a,q,c,e,t);}
Result<void> BeliefSystem::reinforce(AgentPsychState&a,BeliefId id,float evidence)const{if(!std::isfinite(evidence))return make_error(ErrorCode::InvalidArgument,"invalid evidence");auto it=std::find_if(a.beliefs.begin(),a.beliefs.end(),[&](const auto&b){return b.id==id;});if(it==a.beliefs.end())return make_error(ErrorCode::InvalidArgument,"belief does not exist");const float e=std::clamp(evidence,-1.0f,1.0f);if(e>=0)it->certainty+= (1.0f-it->certainty)*e;else it->certainty*=1.0f+e;it->certainty=std::clamp(it->certainty,0.0f,1.0f);++it->evidence_count;return {};}
const BeliefState* BeliefSystem::find(const AgentPsychState&a,const Proposition&p)const noexcept{auto it=std::find_if(a.beliefs.begin(),a.beliefs.end(),[&](const auto&b){return equivalent(b.proposition,p)||contradicts(b.proposition,p);});return it==a.beliefs.end()?nullptr:&*it;}
Result<BeliefUpdate> BeliefSystem::update(AgentPsychState&a,const BeliefEvidence&e)const{if(!e.proposition.predicate.valid()||!e.proposition.name_space.valid()||!std::isfinite(e.strength)||!std::isfinite(e.source_trust))return make_error(ErrorCode::InvalidArgument,"invalid belief evidence");auto it=std::find_if(a.beliefs.begin(),a.beliefs.end(),[&](const auto&b){return equivalent(b.proposition,e.proposition)||contradicts(b.proposition,e.proposition);});const float strength=std::clamp(e.strength,0.0f,1.0f);const float trust=std::clamp(e.source_trust,0.0f,1.0f);const auto pd=PersonalitySystem{}.derive(a.personality);const float resistance=std::clamp(pd.belief_rigidity+(it==a.beliefs.end()?0.0f:0.25f*std::abs(it->emotional_load)),0.0f,0.95f);const float effective=strength*(0.35f+0.65f*trust)*(1.0f-0.65f*resistance);if(it==a.beliefs.end()){auto id=add(a,e.proposition,std::clamp(0.2f+0.75f*effective,0.0f,1.0f),e.emotional_load,e.observed_at,e.source,e.source_agent);if(!id)return *id.error_if();return BeliefUpdate{*id.value_if(),true,false,0.0f,a.beliefs.back().certainty};}BeliefUpdate u{};u.id=it->id;u.old_certainty=it->certainty;const bool same=equivalent(it->proposition,e.proposition);if(same){it->certainty=std::clamp(it->certainty+(1.0f-it->certainty)*effective,0.0f,1.0f);}else{const float remaining=it->certainty-effective;if(remaining<0.0f){it->proposition=e.proposition;it->certainty=std::clamp(-remaining+0.15f*effective,0.0f,1.0f);u.flipped=true;}else it->certainty=remaining;}it->emotional_load=std::clamp(0.7f*it->emotional_load+0.3f*e.emotional_load,-1.0f,1.0f);it->source=e.source;it->source_agent=e.source_agent;it->updated_at=e.observed_at;++it->evidence_count;u.new_certainty=it->certainty;return u;}
}
